/// Decodes a table of little-endian `u8`/`u16` entries into the narrow type this crate indexes with.
fn decode<const N: usize>(t: &Table, size: usize) -> [u8; N] {
    let b = t.get();
    assert_eq!(b.len(), N * size);
    std::array::from_fn(|i| {
        let v = if size == 1 { b[i] as u16 } else { u16::from_le_bytes([b[i * 2], b[i * 2 + 1]]) };
        u8::try_from(v).expect("parser table entry out of range")
    })
}

